//
// The memory bound both read-only SQL surfaces share. Validate (sqlguard.go)
// decides whether a statement may run at all; this file decides how large a
// single value that statement is allowed to build. Which surfaces enforce it,
// and why it has one home, is in the package doc on sqlguard.go.

package sqlguard

import (
	"context"
	"database/sql"
	"errors"
	"fmt"

	"modernc.org/sqlite"
	sqlite3 "modernc.org/sqlite/lib"
)

// MaxCellBytes caps the length of any string or blob SQLite will build on a
// connection CapConn prepared (SQLITE_LIMIT_LENGTH).
//
// The result budget cannot do this job: bound.SQLScanState.Add marshals a row
// to JSON before comparing it to the 60 000-byte budget, so a single oversized
// cell is materialised whole in this process before any cap applies — measured
// against the real archive, `SELECT hex(zeroblob(100000000))` peaked at 1.32 GB
// RSS and `SELECT group_concat(data) FROM resources` at 626 MB, with neither
// the byte budget nor the 5 s deadline firing.
//
// The value is 4 MiB rather than something near the result budget because this
// limit also refuses a read that merely TOUCHES a stored value longer than it,
// even `SELECT length(x)` or `substr(x,1,10)`, which answer SQLITE_TOOBIG. So
// the cap has to clear the largest archived row with room to spare: the real
// archive's largest today is 145 795 bytes (sleep_detail), then 109 909
// (activity_splits). 4 MiB leaves ~28x headroom for a series that grows, while
// still refusing the values that cost hundreds of megabytes to build.
const MaxCellBytes = 4 << 20

// CapConn checks out one connection from db and caps the length of any value
// SQLite will build on it. sqlite.Limit binds to this connection instance
// rather than to the pool, so the cap has to be set here and the query has to
// run on this same connection; a cap set on any other connection is
// decorative. The connection is closed before any error is returned, so a
// caller that gets an error owes nothing.
//
// The returned connection stays checked out until the caller closes it. What
// that costs the caller depends on the caller's own pool: a caller that runs a
// second query on db while holding this connection needs a pool that can serve
// both.
func CapConn(ctx context.Context, db *sql.DB) (*sql.Conn, error) {
	conn, err := db.Conn(ctx)
	if err != nil {
		return nil, fmt.Errorf("opening a read-only connection to the local archive: %w", err)
	}
	if _, err := sqlite.Limit(conn, sqlite3.SQLITE_LIMIT_LENGTH, MaxCellBytes); err != nil {
		_ = conn.Close()
		return nil, fmt.Errorf("capping the value size on the archive connection: %w", err)
	}
	return conn, nil
}

// IsValueTooBig reports whether SQLite refused a value for exceeding
// SQLITE_LIMIT_LENGTH. The driver surfaces every step failure as *sqlite.Error
// with the result code (SQLITE_TOOBIG = 18) from (*rows).Next, and
// database/sql passes it through unwrapped, so the code is the whole test: a
// text match would also claim an unrelated error whose SQL happens to quote
// the phrase.
func IsValueTooBig(err error) bool {
	if err == nil {
		return false
	}
	var coded interface{ Code() int }
	return errors.As(err, &coded) && coded.Code() == sqlite3.SQLITE_TOOBIG
}
